import logging
from taf.converters.base import base
from taf.converters.sherpa.factory import SherpaConverterFactorySelector, DockerContainerFactorySelector
from taf.converters.sherpa.docker_container import DockerContainer

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class sherpa(base):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_sherpa_converter(  # noqa: C901
            self,
            name,
            file_path_pattern,
            executor=None,
            sudo_password=None,
            output_path=None,
            docker_container=None,
            sherpa_executable=None,
            sherpa_command_duration=None,
            sherpa_command_macro_period=None):
        """
        Create a converter to convert Sherpa CSV files from pcap.

        To ease automatic tests conversion to a CSV file is done by this keyword in conjunction with the "convert"
        keyword. Sherpa is only available for 5G. It is not for 4G/LTE L2 traces.

        :param str name: name of the converter
        :param str executor: (optional) sherpa host VM info host, user, password,in dict format. This is not required in
            case sherpa container is used or sherpa tool is available in localhost
        :param str sudo_password: (optional) sherpa host VM password for sudo. This is not required in case sherpa
            container is used.
        :param str docker_container: (optional) alias of previously created docker container. This parameter should not
            be passed with executor or sudo_password parameters.
        :param str file_path_pattern: file paths (wildcards allowed, e. g.: "\\*_gnb_*.pcap")
        :param str output_path: (optional) default value is '/tmp'. converted file destination path.
        :param str sherpa_executable: (optional) default value is '/opt/Nokia/Sherpa_5G_18/Sherpa.run'
        :param str sherpa_command_duration: (optional) default value is 120
        :param str sherpa_command_macro_period: (optional) default value is 1000

        Example:

        Case 1: When sherpa tool is available in localhost (Standard case for a UTE-VM)

        .. code-block:: robotframework

            ***Settings ***
            Library    taf.converters.sherpa    WITH NAME    sherpa

            ***TEST CASES ***
            Convert pcap to sherpa csv
                sherpa.create sherpa converter
                    ...    name=sherpa
                    ...    file_path_pattern=/tmp/testputter/*.pcap
                    ...    output_path=/tmp/testgetter
                sherpa.setup    sherpa
                sherpa.convert    sherpa
                sherpa.teardown    sherpa

        Case 2: When sherpa tool is available in remotehost

        .. code-block:: robotframework

            ***Settings ***
            Library    taf.converters.sherpa    WITH NAME    sherpa

            ***TEST CASES ***
            Convert pcap to sherpa csv
                ${executor}=  Create Dictionary
                ...    host=10.131.225.19
                ...    user=ute
                ...    password=ute
                sherpa.create sherpa converter
                ...    name=sherpa
                ...    executor=${executor}
                ...    sudo_password=ute
                ...    file_path_pattern=/tmp/testputter/*.pcap
                ...    output_path=/tmp/testgetter
                sherpa.setup    sherpa
                sherpa.convert    sherpa
                sherpa.teardown    sherpa

        Case 3: When sherpa container is available in localhost

        .. code-block:: robotframework

            ***Settings ***
            Library    taf.converters.sherpa    WITH NAME    sherpa

            ***TEST CASES ***
            Convert pcap to sherpa csv
                sherpa.create docker container
                ...    name=dockercontainer
                sherpa.create sherpa converter
                ...    name=sherpa
                ...    file_path_pattern=/tmp/testputter/*.pcap
                ...    output_path=/tmp/testgetter
                ...    docker_container=dockercontainer
                sherpa.setup    sherpa
                sherpa.convert    sherpa
                sherpa.teardown    sherpa

        Case 4: When sherpa container is available in remotehost

        .. code-block:: robotframework

            ***Settings ***
            Library    taf.converters.sherpa    WITH NAME    sherpa

            ***TEST CASES ***
            Convert pcap to sherpa csv
                ${executor}=  Create Dictionary
                ...    host=10.131.225.19
                ...    user=ute
                ...    password=ute
                sherpa.create docker container
                ...    name=dockercontainer
                ...    executor=${executor}
                ...    sudo_password=ute
                sherpa.create sherpa converter
                ...    name=sherpa
                ...    file_path_pattern=/tmp/testputter/*.pcap
                ...    output_path=/tmp/testgetter
                ...    docker_container=dockercontainer
                sherpa.setup    sherpa
                sherpa.convert    sherpa
                sherpa.teardown    sherpa

        For more Examples please refer:
        https://confluence.int.net.nokia.com/display/CV/Sherpa_Converters+Example

        For more detail on Converters please refer:
        https://confluence.int.net.nokia.com/display/CV/Converters
        """
        logger.warning("The taf.converters.sherpa library is deprecated and will be removed in a future release.")
        logger.info("Creating Converter with alias: " + name)
        configuration = {
            'name': name,
            'file_path_pattern': file_path_pattern}
        configuration = {
            'name': name,
            'file_path_pattern': file_path_pattern}
        existing_arguments = {}
        if docker_container is not None:
            existing_arguments["docker_container"] = self.get_alias_value(docker_container)
            if not isinstance(existing_arguments["docker_container"], DockerContainer):
                raise RuntimeError(
                    "No docker class instance is available with alias name: {}".format(docker_container))
            if executor is not None:
                raise RuntimeError("executor is not allowed to pass with docker_container")
            if sudo_password is not None:
                raise RuntimeError("sudo_password is not allowed to pass with docker_container")
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["container_start_timeout", "sherpa_command_duration", "sherpa_command_macro_period",
                                  "executor", "output_path", "sherpa_executable"] and parameter_value is not None:
                configuration[parameter_name] = parameter_value
        converter = SherpaConverterFactorySelector().create(
            configuration=configuration,
            existing_arguments=existing_arguments)
        logger.info(name + " converter created successfully")
        self.set_alias(name, converter)

    def create_docker_container(  # noqa: C901
            self,
            name,
            executor=None,
            sudo_password=None,
            sherpa_image=None,
            docker_port1=None,
            docker_port2=None,
            docker_v1_mount=None,
            sherpa_licence=None,
            tool_licence_path=None,
            container_start_timeout=None):
        """
        Create a container class which can be further used in Sherpa Converter.

        To ease setup of Sherpa container which can be used further used in Sherpa Converter. This class helps to
        automate start and stop of Sherpa container.

        :param str name: name of the converter
        :param str executor: (optional) sherpa host VM info host, user, password,in dict format.
        :param str sudo_password: (optional) sherpa host VM password for sudo.
        :param str sherpa_image: (optional) default value is 'sherpa_latest'. It is recommended to use docker tag option
            to tag latest sherpa image in sherpa vm host.
        :param str docker_port1: (optional) default value is 7080.
        :param str docker_port2: (optional) default value is 7900.
        :param str docker_v1_mount: (optional) default value is '/dev/shm1:/dev/shm'.
        :param str sherpa_licence: (optional) default value is '/root/license.lic'.
        :param str tool_licence_path: (optional) default value is '/home/ubuntu/.config/NOKIA/Sherpa5G_18/'.
        :param str container_start_timeout: (optional) default value is 60

        Please refer example of Sherpa Converter (Case3 and Case4)
        """
        logger.warning(
            "The Sherpa Docker container functionality is deprecated and will be removed in a future release.")
        logger.info("Creating Docker Container with alias: " + name)
        configuration = {"name": name}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["sherpa_image", "docker_port1", "docker_port2", "docker_v1_mount", "sherpa_licence",
                                  "tool_licence_path", "executor", "sudo_password"] and parameter_value is not None:
                configuration[parameter_name] = parameter_value
        container = DockerContainerFactorySelector().create(
            configuration=configuration,
            existing_arguments={})
        logger.info(name + " docker container created successfully")
        self.set_alias(name, container)
